"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["69501"],{89650(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.obrigatoriedade_invalida","status":422,"titulo":"A obrigatoriedade \xe9 SEMPRE ou NUNCA, sem predicado, ou QUANDO, com predicado"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.obrigatoriedade_invalida","requisitos":[],"oQueAconteceu":["Um item, um grupo ou um termo do `conteudo` do modelo, enviado na cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`), declara uma obrigatoriedade que n\xe3o combina com o predicado. A obrigatoriedade \xe9 `SEMPRE` ou `NUNCA`, e ent\xe3o `predicadoObrigatoriedade` n\xe3o \xe9 enviado, ou \xe9 `QUANDO`, e ent\xe3o o predicado \xe9 obrigat\xf3rio. Cai aqui tamb\xe9m um valor que n\xe3o seja um desses tr\xeas, escrito exatamente assim, em mai\xfasculas, e a obrigatoriedade ausente em item e grupo, onde o campo \xe9 opcional no JSON. No termo, o campo \xe9 n\xe3o anul\xe1vel e a aus\xeancia \xe9 recusada antes, com 400 e sem c\xf3digo do cat\xe1logo.","A recusa vem na lista `errors` da resposta, com `field` igual a `conteudo.itens[i].obrigatoriedade`, `conteudo.grupos[i].obrigatoriedade` ou `conteudo.termos[i].obrigatoriedade`. O predicado de `QUANDO` malformado \xe9 outra recusa, com outro c\xf3digo, no campo do predicado. Enquanto o conte\xfado tem recusas de leitura como esta, as regras que dependem do conte\xfado inteiro, como a estrutura do formul\xe1rio e os pressupostos, n\xe3o s\xe3o conferidas. Nada \xe9 gravado.","Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado). S\xf3 a leitura do corpo vem antes da busca: campo n\xe3o anul\xe1vel ausente ou nulo (como `nome`) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, mesmo com `{id}` inexistente."],"comoResolver":["Corrija o item, grupo ou termo indicado em `field`: use `SEMPRE` ou `NUNCA` sem predicado, ou `QUANDO` com `predicadoObrigatoriedade`."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);